import * as React from 'react';
import './styles.scss';

import axios from 'axios';
import { AppConfig, extractErrorMessage } from 'bi-internal/core';
import { formatNumberWithString, lpeRun, vizel_config } from 'bi-internal/utils';
import { AlertsVC } from 'bi-internal/ui';
import { AtlasHierarchyValuesService } from 'bi-internal/services';
import { extractVarsFromVarsModel } from 'bi-internal/utils';
import {IVizelProps} from "bi-internal/defs/types";


class TreeTableSimple extends React.Component<IVizelProps> {
  public state: {
    tree: any[];
    expanded: { [id: string]: boolean };
    ltTitle: string;
    dataTotal: any[];
  } = {
    tree: null,
    expanded: {},
    ltTitle: '',
    dataTotal: [],
  };

  public constructor(props) {
    super(props);
    const saveAbilities = [];
    if (Array.isArray(props.cfg?.report))
      props.cfg.report.forEach((r) => saveAbilities.push(`report-${r.output}`));
    if (props.onVizelPropertiesChanged) props.onVizelPropertiesChanged({ saveAbilities }, this);
  }

  public componentDidMount() {
    this._reloadData();
  }

  public componentDidUpdate(prevProps: Readonly<{}>) {
    if (this.props.subspace !== prevProps.subspace) {
      this._reloadData();
    }
  }

  public save = async (saveAbility: string): Promise<void> => {
    const { cfg, subspace, schema_name } = this.props;
    const rawCfg = cfg;

    if (rawCfg.report && saveAbility.match(/report/)) {
      const varsService = AtlasHierarchyValuesService.createInstance(this.props.schema_name);
      await varsService.whenReady();
      const vars = extractVarsFromVarsModel(varsService.getModel());

      const output = saveAbility.replace(/^[report-]*/, '');
      const report = rawCfg.report.find((r) => r.output === output);
      const extension = report.output === 'xlsx' && AppConfig.hasFeature('OldExcelSave') ? 'xls' : report.output;
      const url = '/srv/reports/generate';
      const body = {
        report: { ...report },
        sources: [
          {
            dataSource: {
              ...rawCfg.dataSource,
              limit: undefined,
              filters: subspace.filters,
              atlas: schema_name,
              vars,
            },
            title: cfg.title,
            view_class: 'tree-table-simple',
          },
        ],
      };

      try {
        const request = await axios.post(url, body, { responseType: 'blob' });
        const urlSave = URL.createObjectURL(request.data);
        const link = document.createElement('a');
        link.setAttribute('href', urlSave);
        link.setAttribute('download', `${report.title}.${extension}`);
        link.setAttribute('target', '_blank');
        link.style.display = 'none';
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        return new Promise((resolve) => resolve());
      } catch (error) {
        console.error(error);
        try {                                                                                       // Там может быть не json
          const errors = JSON.parse(await error.response.data.text());
          AlertsVC.getInstance().pushDangerAlert(extractErrorMessage(errors));
        } catch (err2) {
          AlertsVC.getInstance().pushDangerAlert(extractErrorMessage(error));
        }
      }
    }
    return new Promise((resolve) => resolve());
  };

  private _reloadData = async () => {
    const { dp, subspace, cfg } = this.props;
    const sortBy = cfg?.dataSource?.sortBy?.split(';')?.[0] || '';
    let dataTotal = await dp.getTotalVector(subspace);
    const matrix = await dp.getMatrixYX(subspace);

    const { xs, ys, dimensions } = subspace;
    const tree = makeXsTree(cfg, xs, ys, matrix, sortBy);
    let ltTitle =
      subspace.xs?.[0]?.axisIds
        ?.map((axisId) => {
          return dimensions?.find((d) => d.id === axisId)?.title ?? ' - ';
        })
        .filter(Boolean)
        .join(' / ') ?? '';

    const hasSubtotals = xs.some((x) => String(x.id).includes('∑'));
    if (!hasSubtotals) {
      dataTotal = ys.map((y, yi) => (tree || []).reduce((a, item) => a + item.values[yi], 0));
    }

    const hasExpandAll = vizel_config.getOption(cfg, 'ExpandAll');
    let expanded = {};

    if (hasExpandAll) {
      const walkItem = (treeItem) => {
        if (treeItem.children) {
          expanded[treeItem.fullId] = true;
          treeItem.children.forEach(walkItem);
        }
      };
      tree.forEach(walkItem);
    }

    this.setState({ ltTitle, tree, dataTotal, expanded });
  };

  private _onClickItem(e, renderItem) {
    e.stopPropagation();
    let expanded = { ...this.state.expanded };
    if (expanded[renderItem.fullId]) delete expanded[renderItem.fullId];
    else expanded[renderItem.fullId] = true;
    this.setState({ expanded });
  }

  private _onClickDataPoint(event, { v, seriesIndex, categoryIndex, level }) {
    const { subspace } = this.props;
    // @ts-ignore
    const controller = this.props.controller ?? this.props.cfg.controller;
    const z = subspace.getZ(0);
    const y = subspace.getY(seriesIndex);
    let x = subspace.getX(categoryIndex);

    if (!z || !y || !x) return;

    x = { ...x, ids: x.ids.slice(0, level + 1), axisIds: x.axisIds.slice(0, level + 1) };

    let filters = {};
    if (subspace.koob) {
      const modelFilter = { ...subspace.filters };
      [z, y, x].forEach((axis) => {
        (axis?.axisIds ?? []).forEach((axisId, i) => {
          const id = axis.ids[i];
          const formula = axis.formula[i].replace(/:.*/g, '');
          if (axisId !== 'measures') modelFilter[formula] = ['=', id];
        });
      });
      filters = modelFilter;
    }

    const { m, l, p } = subspace.getMLP(z, y, x);
    controller.handleVCPClick(event, { x, y, z, m, l, p, v, filters });
  }

  public renderTree(tree) {
    const { subspace, cfg } = this.props;
    const { expanded } = this.state;
    return tree.map((renderItem, xi) => {
      const xCellStyle = this._getStyle('dimension', {
        xi: renderItem.index,
        level: renderItem.level,
        children: renderItem.children,
      });
      return (
        <>
          <tr key={xi} className={renderItem.level >= 3 ? 'hasValue' : 'hasNoValue'}>
            <td
              onClick={(e) =>
                this._onClickDataPoint(e, {
                  v: renderItem.title,
                  categoryIndex: renderItem.index,
                  seriesIndex: 0,
                  level: renderItem.level,
                })
              }
              style={{ ...xCellStyle, paddingLeft: `${2.5 * renderItem.level + 1}rem` }}
              title={renderItem.title}
            >
              {!!renderItem.children &&
                (xCellStyle.expandable !== false ? (
                  <span className="CustomVizelTree__CollapseIcon" onClick={(e) => this._onClickItem(e, renderItem)}>
                    {expanded[renderItem.fullId] ? '-' : '+'}
                  </span>
                ) : (
                  <span className="CustomVizelTree__Padding" />
                ))}
              {renderItem.title}
            </td>

            {subspace.ys.map((y, yi) => {
              const value = renderItem.values[yi];
              const format = vizel_config.getLegendItem(cfg, y)?.format;
              const fValue = !isNaN(value) ? formatNumberWithString(value, format || '-# ###.00') : value;
              const yCellStyle = this._getStyle('measure', { xi: renderItem.index, yi, values: renderItem.values, level: renderItem.level });
              return !yCellStyle.hidden && (
                <td
                  key={yi}
                  className={renderItem.level >= 3 ? 'value' : 'null'}
                  onClick={(e) =>
                    this._onClickDataPoint(e, {
                      v: renderItem.values[yi],
                      categoryIndex: renderItem.index,
                      seriesIndex: yi,
                      level: renderItem.level,
                    })
                  }
                  title={fValue}
                  style={yCellStyle}
                >
                  {fValue}
                </td>
              );
            })}
          </tr>

          {!!renderItem.children && xCellStyle.expandable !== false && expanded[renderItem.fullId] && this.renderTree(renderItem.children)}
        </>
      );
    });
  }

  private _expandAll = () => {
    const { tree } = this.state;
    let expanded = {};

    const walkItem = (treeItem) => {
      if (treeItem.children) {
        expanded[treeItem.fullId] = true;
        treeItem.children.forEach(walkItem);
      }
    };
    tree.forEach(walkItem);
    this.setState({ expanded });
  };

  private _collapseAll = () => {
    this.setState({ expanded: {} });
  };

  private _getStyle = (type = 'dimension', { xi, yi, values, level, children }: any) => {
    const { cfg, subspace } = this.props;
    const display = cfg?.display ?? {};
    const widths = display?.widths || [];
    let x = subspace.getX(xi || 0);
    const y = subspace.getY(yi);
    let li = type === 'measure'
      ? vizel_config.getLegendItem(cfg, y)
      : cfg?.dataSource?.style[x.axisIds[level]] || vizel_config.getLegendItem(cfg, x) || {};

    const valuesMap = {};
    if (values) {
      subspace.ys.forEach((sy, syi) => (valuesMap[sy.id] = values[syi]));
    }

    let style: any = {};
    if (level != null) x = { ...x, axisIds: x.axisIds.slice(0, level + 1) };
    let context = getLpeContext(x, y, valuesMap, children || []);

    style = {
      ...style,
      ...li,
      ...li.textStyle,
      color: processLpe(li.textStyle?.color, context),
      backgroundColor: processLpe(li.backgroundColor, context),
      width: widths.length > yi + 1 ? widths[yi + 1] : li?.width,
      expandable: processLpe(li.expandable, context),
      hidden: Array.isArray(li.options) && li.options.includes('Hidden'),
    };

    if (li.headerStyle) {
      style = {
        ...style,
        headerStyle: {
          ...li.headerStyle,
          ...li.headerStyle.textStyle,
          color: processLpe(li.headerStyle.textStyle?.color, context),
          backgroundColor: processLpe(li.headerStyle.backgroundColor, context),
        },
      };
    }

    if (li.footerStyle) {
      style = {
        ...style,
        footerStyle: {
          ...li.footerStyle,
          ...li.footerStyle.textStyle,
          color: processLpe(li.footerStyle.textStyle?.color, context),
          backgroundColor: processLpe(li.footerStyle.backgroundColor, context),
        },
      };
    }

    return style;
  };

  public render() {
    const { cfg, subspace } = this.props;
    const { tree, ltTitle, expanded, dataTotal } = this.state;
    if (!tree) return null;
    const displayOverall = vizel_config.getOption(cfg, 'DisplayOverall');
    const hasExpandAllButton = vizel_config.getOption(cfg, 'ExpandAllButton');
    const display = cfg?.display ?? {};
    const xStyle = this._getStyle('dimension', {});

    return (
      <div className="TreeTableSimple">
        <table>
          <thead>
            <tr>
              <th
                className="TreeTableSimple__Th0"
                style={{ ...xStyle.headerStyle, width: xStyle.width }}
                title={display?.dimensionsTitle || ltTitle}
              >
                {!!hasExpandAllButton &&
                  (Object.values(expanded).length === 0 ? (
                    <IconExpand onClick={this._expandAll} />
                  ) : (
                    <IconCollapse onClick={this._collapseAll} />
                  ))}
                <span>{display?.dimensionsTitle || ltTitle}</span>
              </th>
              {subspace.ys.map((y, yi) => {
                const yStyle = this._getStyle('measure', { yi });
                return !yStyle.hidden && (
                  <th key={yi} style={{ ...yStyle.headerStyle, width: yStyle.width }} title={y.title}>
                    {y.title}
                  </th>
                );
              })}
            </tr>
          </thead>
          <tbody>{this.renderTree(tree)}</tbody>
          {!!displayOverall && (
            <tfoot>
              <tr>
                <th style={{ ...xStyle?.footerStyle }}>Итого</th>
                {subspace.ys.map((y, yi) => {
                  const yStyle = this._getStyle('measure', { yi });
                  return !yStyle.hidden && (
                    <td key={yi} style={{ ...yStyle?.footerStyle }}>
                      {formatNumberWithString(dataTotal[yi] ?? 0, yStyle.format || '-# ###.00')}
                    </td>
                  );
                })}
              </tr>
            </tfoot>
          )}
        </table>
      </div>
    );
  }
}
export default TreeTableSimple;

function makeXsTree(cfg: any, xs: any[], ys: any[], data: any[], sortBy: string = ''): any[] {
  let tree = [];
  let cache = {};
  let sort =
    sortBy !== ''
      ? { index: ys.findIndex((el) => el.id === sortBy.slice(1)), dir: sortBy[0] === '-' ? 'desc' : 'asc' }
      : null;
  const hasSubtotals = xs.some((x) => x.id.includes('∑'));
  xs = xs.map((x, xi) => ({ ...x, index: xi }));
  if (hasSubtotals) xs.sort(liftSubtotals);
  xs.forEach((x, xi) => {
    const ids = x.ids;
    let combinedId = '';
    let parentItem: any = null;
    for (let i = 0; i < ids.length; i++) {
      const isSubtotal = ids[i]?.startsWith('∑');
      combinedId += ':' + ids[i];
      if (!cache[combinedId] && !isSubtotal) {
        const level = parentItem ? parentItem.level + 1 : 0;
        const li = cfg?.dataSource?.style[x.axisIds[level]] || {};
        const context = getLpeContext(x);
        const title = processLpe(li.title || x.titles[i], context);
        const newItem = {
          title,
          level,
          id: ids[i],
          index: x.index,
          parent: parentItem,
          fullId: combinedId,
          children: i === ids.length - 1 ? null : [],
          fullTitle: parentItem ? parentItem.fullTitle + ' / ' + title : title,
          values: ys.map((y, yi) => (hasSubtotals ? data[yi][x.index] : 0)),
        };
        if (parentItem) parentItem.children.push(newItem);
        else tree.push(newItem);
        cache[combinedId] = newItem;
      }
      parentItem = cache[combinedId];
    }
    if (!hasSubtotals) {
      ys.forEach((y, yi) => {
        for (let i = parentItem; !!i; i = i.parent) {
          const value = data[yi][xi] || 0;
          if (!isNaN(value)) i.values[yi] += value;
          else i.values[yi] = value;
        }
      });
    }
  });
  let sortingCallback = (c1, c2) =>
    sort
      ? sort.dir === 'desc'
        ? c2.values[sort.index] - c1.values[sort.index]
        : c1.values[sort.index] - c2.values[sort.index]
      : c2.values[1] - c1.values[1];
  const sortRec = (tree) => {
    if (!tree.children) return;
    tree.children.forEach(sortRec);
    tree.children.sort(sortingCallback);
  };

  // console.time('tree::sort');
  sortRec({ children: tree });
  // console.timeEnd('tree::sort');

  return tree;
}
const liftSubtotals = (a: any, b: any) => {
  const findSubtotalIndex = (row: any) => row.ids.findIndex(id => id?.startsWith('∑'));

  const aIndex = findSubtotalIndex(a);
  const bIndex = findSubtotalIndex(b);

  if (aIndex !== -1 && bIndex !== -1) return aIndex - bIndex;
  if (aIndex !== -1) return -1;
  if (bIndex !== -1) return 1;

  return 0;
};
const processLpe = (value, context) => (String(value).startsWith('lpe:') ? lpeRun(value, context) : value);
const getLpeContext = (x, y?, valuesMap?, children?) => {
  let context = { children };
  [x, y].filter(Boolean).map((entity) => {
    entity.axisIds?.map((axisId, axisIndex) => {
      if (axisId !== 'measures') {
        context[axisId] = entity.ids[axisIndex];
      } else {
        // @ts-ignore
        const value = valuesMap[entity.id] || x._raw?.[entity.id];
        context = { ...context, ...valuesMap, value, v: value };
      }
    });
  });
  return context;
};

const IconCollapse = ({ onClick }) => (
  <svg xmlns="http://www.w3.org/2000/svg" version="1.1" x="0px" y="0px" viewBox="0 0 100 100" onClick={onClick}>
    <path d="M29.6,50.8l3.7,3.4l16.6-18.2l16.9,17.9l3.6-3.4L49.8,28.6L29.6,50.8z" />
    <path d="M29.6,68l3.7,3.4l16.6-18.2l16.9,17.9l3.6-3.4L49.8,45.9L29.6,68z" />
  </svg>
);

const IconExpand = ({ onClick }) => (
  <svg xmlns="http://www.w3.org/2000/svg" version="1.1" x="0px" y="0px" viewBox="0 0 100 100" onClick={onClick}>
    <path d="M70.4460068,51.6058578l-3.6915665-3.3786774L50.1276855,66.4678879L33.1863136,48.5190582l-3.6323166,3.4423599  l20.6347618,21.8114014L70.4460068,51.6058578z" />
    <path d="M70.4460068,34.3558578l-3.6915665-3.3786774L50.1276855,49.2178879L33.1863136,31.2690582l-3.6323166,3.4423599  l20.6347618,21.8114014L70.4460068,34.3558578z" />
  </svg>
);
